class Solution:
    def stepBack(self, ratings: List[int]) -> List[int]:
        count = [0] * 101
        for x in ratings:
            count[x] += 1
        buf = []
        def build():
            if len(buf) == len(ratings):
                return list(buf) if buf < ratings else None
            for v in range(100, -1, -1):
                if count[v]:
                    count[v] -= 1
                    buf.append(v)
                    found = build()
                    buf.pop()
                    count[v] += 1
                    if found:
                        return found
            return None
        return build() or sorted(ratings, reverse=True)

