class Solution {
    private int[] count = new int[101], buf, target;

    public int[] stepBack(int[] ratings) {
        target = ratings;
        buf = new int[ratings.length];
        for (int x : ratings) count[x]++;
        if (build(0)) return buf;
        int[] out = ratings.clone();
        Arrays.sort(out);
        for (int a = 0, b = out.length - 1; a < b; a++, b--) { int t = out[a]; out[a] = out[b]; out[b] = t; }
        return out;
    }

    private boolean build(int pos) {
        if (pos == buf.length) return Arrays.compare(buf, target) < 0;
        for (int v = 100; v >= 0; v--) {
            if (count[v] == 0) continue;
            count[v]--;
            buf[pos] = v;
            boolean found = build(pos + 1);
            count[v]++;
            if (found) return true;
        }
        return false;
    }
}

