    bool build(size_t pos) {
        if (pos == buf.size()) return buf < target;
        for (int v = 100; v >= 0; v--) {
            if (!count[v]) continue;
            count[v]--;
            buf[pos] = v;
            bool found = build(pos + 1);
            count[v]++;
            if (found) return true;
        }
        return false;
    }

public:
    vector<int> stepBack(vector<int>& ratings) {
        target = ratings;
        buf.assign(ratings.size(), 0);
        for (int x : ratings) count[x]++;
        if (build(0)) return buf;
        vector<int> out = ratings;
        sort(out.rbegin(), out.rend());
        return out;
    }
};

