static int count[101];
static int* buf;
static int* target;
static int len;

static bool build(int pos) {
    if (pos == len) {
        for (int i = 0; i < len; i++) if (buf[i] != target[i]) return buf[i] < target[i];
        return false;
    }
    for (int v = 100; v >= 0; v--) {
        if (!count[v]) continue;
        count[v]--;
        buf[pos] = v;
        bool found = build(pos + 1);
        count[v]++;
        if (found) return true;
    }
    return false;
}

int* stepBack(int* ratings, int ratingsSize, int* returnSize) {
    len = ratingsSize;
    target = ratings;
    buf = malloc(len * sizeof(int));
    memset(count, 0, sizeof count);
    for (int i = 0; i < len; i++) count[ratings[i]]++;
    *returnSize = len;
    if (build(0)) return buf;
    int k = 0;
    for (int v = 100; v >= 0; v--) for (int c = 0; c < count[v]; c++) buf[k++] = v;
    return buf;
}

