class Solution {
    public int[] stepBack(int[] ratings) {
        int[] a = ratings.clone();
        int n = a.length, i = n - 2;
        while (i >= 0 && a[i] <= a[i + 1]) i--;
        int start = i + 1;
        if (i >= 0) {
            int j = n - 1;
            while (a[j] >= a[i]) j--;
            int t = a[i]; a[i] = a[j]; a[j] = t;
        }
        for (int x = start, y = n - 1; x < y; x++, y--) { int t = a[x]; a[x] = a[y]; a[y] = t; }
        return a;
    }
}

