class Solution {
public:
    vector<int> stepBack(vector<int>& ratings) {
        vector<int> a = ratings;
        int n = a.size(), i = n - 2;
        while (i >= 0 && a[i] <= a[i + 1]) i--;
        if (i >= 0) {
            int j = n - 1;
            while (a[j] >= a[i]) j--;
            swap(a[i], a[j]);
        }
        reverse(a.begin() + i + 1, a.end());
        return a;
    }
};

